internal sealed class SongesWindow:Window {
 readonly string file;readonly Stopwatch clock=Stopwatch.StartNew();readonly DispatcherTimer timer;SongesRun run;SongesOcr reader;SongesGameWindow game;bool armed,reading,closed,testing;int generation;long lastRead=-3000,lastSave;TextBlock total,room,combat,depth,status,summary,history,official,previousRuns;ComboBox games;Button arm;Expander connection;string notice="Sélectionnez la fenêtre DOFUS, puis activez la lecture locale.";
 internal SongesWindow(string root,bool test=false,Action back=null){
 testing=test;file=Path.Combine(root,"songes-run.json");run=ReadState(file);Title="Compagnon Dofus · Songes";Width=420;Height=740;MinWidth=360;MinHeight=480;MaxWidth=1000;MaxHeight=1200;Topmost=true;WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;ResizeMode=ResizeMode.CanResizeWithGrip;FontFamily=new FontFamily("Segoe UI");Foreground=CompanionWindow.Ink;Resources=(ResourceDictionary)System.Windows.Markup.XamlReader.Parse(CompanionWindow.Styles);
 var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});Content=CompanionTheme.Shell(grid);grid.Children.Add(CompanionTheme.Header(this,"Le rythme de votre run",testing));
 var quests=CompanionWindow.Button("Parcours",()=>{if(back==null)Close();else{Hide();back();}});var tab=CompanionWindow.Button("Songes",()=>{});tab.Foreground=CompanionWindow.Accent;tab.BorderBrush=CompanionWindow.Accent;var tabs=CompanionTheme.Pair(quests,tab);tabs.Margin=new Thickness(0,0,0,14);Grid.SetRow(tabs,1);grid.Children.Add(tabs);
 var body=new StackPanel{Margin=new Thickness(0,0,3,0)};var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,2);grid.Children.Add(scroll);
 var hero=new StackPanel();var top=new DockPanel();depth=CompanionTheme.Label("",12);top.Children.Add(depth);hero.Children.Add(top);hero.Children.Add(CompanionTheme.Label("TEMPS TOTAL DE LA RUN"));total=CompanionTheme.Number(44);total.Foreground=CompanionWindow.Accent;hero.Children.Add(total);
 hero.Children.Add(new Border{Height=1,Background=CompanionTheme.Line,Margin=new Thickness(0,8,0,14)});
 var roomPanel=new StackPanel();roomPanel.Children.Add(CompanionTheme.Label("DANS CETTE SALLE",9));room=CompanionTheme.Number(24);roomPanel.Children.Add(room);
 var fightPanel=new StackPanel{Margin=new Thickness(10,0,0,0)};fightPanel.Children.Add(CompanionTheme.Label("COMBAT EN COURS",9));combat=CompanionTheme.Number(24);fightPanel.Children.Add(combat);hero.Children.Add(CompanionTheme.Pair(roomPanel,fightPanel));body.Children.Add(CompanionTheme.Card(hero,18));
 status=CompanionWindow.Text("",11,true);status.Margin=new Thickness(2,0,2,12);body.Children.Add(status);
 var officialPanel=new StackPanel();officialPanel.Children.Add(CompanionTheme.Label("BILAN DOFUS"));official=CompanionWindow.Text("",12);officialPanel.Children.Add(official);summary=CompanionWindow.Text("",11,true);officialPanel.Children.Add(summary);body.Children.Add(CompanionTheme.Card(officialPanel));
 history=CompanionWindow.Text("",12,true);history.FontFamily=new FontFamily("Consolas");body.Children.Add(CompanionTheme.Fold("Temps par salle",history));
 previousRuns=CompanionWindow.Text("",12,true);body.Children.Add(CompanionTheme.Fold("Runs précédentes",previousRuns));LoadHistory();
 var setup=new StackPanel();setup.Children.Add(CompanionWindow.Text("Fenêtre à observer",11,true));games=new ComboBox{MinHeight=36};setup.Children.Add(games);setup.Children.Add(CompanionWindow.Button("Actualiser les fenêtres DOFUS",RefreshGames));setup.Children.Add(CompanionWindow.Text("Revenez dans le jeu après activation. Lecture locale, sans conservation des images.",11,true));connection=CompanionTheme.Fold("Connexion au jeu",setup,true);body.Children.Insert(0,connection);
 var manual=new StackPanel();manual.Children.Add(CompanionWindow.Text("Utilisez ces commandes pour corriger une lecture manquée.",11,true));var fightButtons=new WrapPanel();fightButtons.Children.Add(CompanionWindow.Button("Début combat",()=>{run.Resume(clock.ElapsedMilliseconds);run.BeginFight(clock.ElapsedMilliseconds);notice="Combat démarré manuellement.";Save();Update();}));fightButtons.Children.Add(CompanionWindow.Button("Victoire",()=>{if(!run.State.combat){notice="Aucun combat à terminer.";Update();return;}run.Resume(clock.ElapsedMilliseconds);run.EndFight(clock.ElapsedMilliseconds,true);notice="Victoire enregistrée manuellement.";Save();Update();}));fightButtons.Children.Add(CompanionWindow.Button("Défaite",()=>{if(!run.State.combat){notice="Aucun combat à terminer.";Update();return;}run.Resume(clock.ElapsedMilliseconds);run.EndFight(clock.ElapsedMilliseconds,false);notice="Défaite enregistrée, sans valider la salle.";Save();Update();}));manual.Children.Add(fightButtons);
 var correct=new WrapPanel();correct.Children.Add(CompanionWindow.Button("Corriger la salle",Correct));correct.Children.Add(CompanionWindow.Button("Temps officiel",CorrectOfficial));correct.Children.Add(CompanionWindow.Button("Terminer la run",()=>{run.Finish(clock.ElapsedMilliseconds);armed=false;generation++;Save();Update();}));manual.Children.Add(correct);body.Children.Add(CompanionTheme.Fold("Corrections manuelles",manual));
 var help=new StackPanel();help.Children.Add(CompanionWindow.Text("FIN DE TOUR lance le chrono du combat. VICTOIRE ou DÉFAITE l’arrête. La profondeur indique la salle ; marchés et bonus ne comptent pas comme combats. Les vagues restent un seul combat.",11,true));help.Children.Add(CompanionWindow.Text("Le temps total continue entre les combats. La victoire en salle 26 arrête la mesure ; le bilan Songe terminé fournit le temps officiel. Le jeu doit rester au premier plan, avec les repères visibles. Détection expérimentale.",11,true));body.Children.Add(CompanionTheme.Fold("Comprendre la détection",help));
 var footer=new StackPanel{Margin=new Thickness(0,12,0,0)};Grid.SetRow(footer,3);grid.Children.Add(footer);arm=CompanionWindow.Button("Activer la détection",Toggle,true);arm.Margin=new Thickness(0,0,0,6);arm.MinHeight=42;footer.Children.Add(arm);var reset=CompanionWindow.Button("Nouvelle run",Reset);reset.Margin=new Thickness(0);footer.Children.Add(reset);
 timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=async delegate{run.Tick(clock.ElapsedMilliseconds);Update();if(armed&&!reading&&clock.ElapsedMilliseconds-lastRead>=1000)await Scan();if(!testing&&run.State.started&&clock.ElapsedMilliseconds-lastSave>10000)Save();};
 Loaded+=delegate{if(!testing){Left=Math.Max(SystemParameters.WorkArea.Left,SystemParameters.WorkArea.Right-Width-12);Top=SystemParameters.WorkArea.Top+32;RefreshGames();timer.Start();}};
 Closed+=delegate{closed=true;armed=false;generation++;timer.Stop();run.Pause(clock.ElapsedMilliseconds);if(!testing)Save();};Update();
